INSERT INTO `product_categories` VALUES (3,'gdx0fnrzqwhx49vq39xc5edm','Mesin Laser Engrave dan CNC','mesin-laser-engrave-cnc','[{\"type\":\"heading\",\"level\":2,\"children\":[{\"type\":\"text\",\"text\":\"Bingung Memilih Investasi Mesin Laser Cutting & CNC Router yang Tepat untuk Bisnis Anda?\"}]},{\"type\":\"paragraph\",\"children\":[{\"type\":\"text\",\"text\":\"Menambah layanan potong akrilik dan pembuatan plakat membutuhkan akurasi mesin yang prima. Kami memahami kekhawatiran Anda:\"}]},{\"type\":\"list\",\"format\":\"unordered\",\"children\":[{\"type\":\"list-item\",\"children\":[{\"type\":\"text\",\"text\":\"\\\"Apakah mesin laser CO2 ini bisa memotong akrilik tebal dengan hasil tepi yang halus tanpa gosong?\\\"\"}]},{\"type\":\"list-item\",\"children\":[{\"type\":\"text\",\"text\":\"\\\"Bagaimana jika tabung laser (laser tube) cepat melemah sehingga daya potongnya menurun drastis?\\\"\"}]},{\"type\":\"list-item\",\"children\":[{\"type\":\"text\",\"text\":\"\\\"Apakah pengoperasian software CNC router terlalu rumit untuk operator pemula di workshop saya?\\\"\"}]},{\"type\":\"list-item\",\"children\":[{\"type\":\"text\",\"text\":\"\\\"Apakah ada teknisi lokal berpengalaman yang bisa membimbing dari nol hingga instalasi selesai?\\\"\"}]}]},{\"type\":\"quote\",\"children\":[{\"type\":\"text\",\"text\":\"Jika keraguan itu yang sedang Anda rasakan, maka Anda telah berada di halaman yang tepat.\"}]},{\"type\":\"paragraph\",\"children\":[{\"type\":\"text\",\"text\":\"Kami tidak sekadar menjual mesin. Kami hadir sebagai \"},{\"type\":\"text\",\"text\":\"mitra pertumbuhan\",\"bold\":true},{\"type\":\"text\",\"text\":\" bisnis Anda. Setiap mesin yang kami sediakan telah melewati kurasi ketat untuk memastikan Anda mendapatkan \\\"mesin pencetak uang\\\" yang stabil, efisien, dan memiliki nilai jual kembali yang tinggi.\"}]},{\"type\":\"heading\",\"level\":3,\"children\":[{\"type\":\"text\",\"text\":\"Solusi Pemotongan & Ukir Presisi:\"}]},{\"type\":\"paragraph\",\"child